$s='y + 1'; $t=$null;$e=$null; $ast=[System.Management.Automation.Language.Parser]::ParseInput($s,[ref]$t,[ref]$e); Write-Host "Errors:$($e.Count)"; $e|ForEach-Object {Write-Host $_.Message}; $ast.EndBlock.Statements | ForEach-Object {Write-Host "Stmt Type:"$_.GetType().Name; if ($_.PipelineElements) { $_.PipelineElements | ForEach-Object { Write-Host "  Elem Type:"$_.GetType().Name } } }
